%[text] # Exploration
%[text] The eegArtifacts.mlx script illustrates problems and solutions. This live script looks more generally at how simulation parameters affect performance.
%[text:tableOfContents]{"heading":"**Table of Contents**"}
%[text] 
%%
%[text] %[text:anchor:H_D32E8D0B] ## Setup Simulation
%[text] First define the stimulation and recording parameters.
startup; % Make sure all toolboxes are on the path

eegDefaults.reproducible              = true;    % Fix the random number generator to get reproducible results
%[text] Equipment:
eegDefaults.stimulatorSamplingRate    = 1e3;     % Neuroconn (2 kHz)
eegDefaults.recordingSamplingRate     = 5e3;     % 5kHz
eegDefaults.currentResolution         = 1e-6;    % 1 muA
eegDefaults.highPass                  = 0.01;    % Analog filter of the recording amplifier

%[text] Experiment:

eegDefaults.duration                  = 2*60;   % 2 min of data
eegDefaults.tacsFrequency             = 0;
eegDefaults.tacsAmplitude             = 0;
eegDefaults.tdcsMean                  = 0;
%[text] Signals. Setting everything except the background to 0.
eegDefaults.additive                  = 100e-6;   % Background Noise stdev
eegDefaults.lfpAmplitude              = 0;
eegDefaults.multiplicative            = 0;
eegDefaults.zAmplitude                = 0;

%[text] And setup the base parameters for artifiact removal
arDefaults.slide                     = false;   % No sliding segment
arDefaults.slack                     = 5e-3;    % 5 ms to realign segments
arDefaults.nrSegsPerWindow           = 10;      % 10 segments to average artifact
arDefaults.pcaNr                     = 2;       % First two PC are removed
arDefaults.pcaVarExplained           = Inf;     % Ignore explained variance, always remove 2.
arDefaults.pcaNrSegsPerWindow        = Inf;     % Use all segments (plus the tACS signal; below) to determine basis set.
arDefaults.referenceSegment          = 1;       % Align to first segment
arDefaults.recordingSamplingRate      = eegDefaults.recordingSamplingRate; % Match to the recording
%[text] ## Signal frequency dependence
%[text] The above analysis focuses only on a single intrinsic oscillation, here I do repeat this for a range of frequencies to show that the relative performance of the methods is approximately the same no matter what the neural signal is. 
eeg                  = artSim(eegDefaults); % Start fresh
eeg.lfpAmplitude     = 100e-6;    % Oscillation peak amplitude
eeg.lfpPeakWidth     = 1;        % Oscillation bandwidth.
eeg.tacsAmplitude    = 1e-3;    % 1 mA -> 1 mV artifact
eeg.tacsFrequency    = 8;      %  8 Hz

ar                 = arDefaults;
ar.tacsFrequency  = eeg.tacsFrequency;
ar.segmentDuration       = 30/eeg.tacsFrequency;      % 30 cycles per segment

methods = ["FASTR","FBAR", "RBAR"];
signalFreqs = 2.^(0:5);  % Test these frequencies
nrFreqs = numel(signalFreqs);
nrMethods = numel(methods);
forbiddenBand = nan(nrFreqs,nrMethods);
forbidden = nan(nrFreqs,nrMethods);
mre = nan(nrFreqs,nrMethods);
for m=1:nrMethods %[output:group:7233e4c3]
    for  f = 1:nrFreqs
        eeg.lfpFrequency = signalFreqs(f);
        results = simPlotEEG(eeg,ar,methods(m),freqRes =0.1,axs=[nan nan nan]);  % Same analysis as above, without figure %[output:8b58dd8f] %[output:6e4b9e7d] %[output:62016eb3] %[output:6bb500fd] %[output:3cf346e1] %[output:4b206cc6] %[output:3466dae6] %[output:968ddb7b] %[output:011c2a31] %[output:666917b4] %[output:30c75615] %[output:32765df3] %[output:89b9cc6d]
        forbiddenBand(f,m) = results.forbiddenBand;
        forbidden(f,m) = results.forbidden;
        mre(f,m) = results.meanPctError;
    end
end %[output:group:7233e4c3]
clf; %[output:44494285]
subplot(1,2,1) %[output:44494285]
plot(signalFreqs,forbidden) %[output:44494285]
xlabel 'Signal Frequency (Hz)' %[output:44494285]
ylabel 'Forbidden (Hz)' %[output:44494285]

subplot(1,2,2) %[output:44494285]
plot(signalFreqs,forbiddenBand) %[output:44494285]
xlabel 'Signal Frequency (Hz)' %[output:44494285]
ylabel 'Forbidden in-band (Hz)' %[output:44494285]
legend(cellstr(methods)) %[output:44494285]
mean(forbidden) %[output:10ca93cd]
std(forbidden) %[output:234d39f7]
mean(mre) %[output:9f816cd6]
%[text] The figure shows that FASTR  performs poorly across all signal frequencies while FBAR and RBAR create relatively small forbidden bands, as long as the signal frequency (i.e. the neural oscillation) is distinct from the tACS frequency.
%%
%[text] ## Segment length dependence
%[text] Longer segments generally result in better artifact estimation (as long as the artifact is not substantially the same as the neural signal) and therefore better artifact removal. 
%[text] Note, however, that this comes at a cost of a reduced ability to follow changes in the artifacts over time (i.e. dealing with non-stationary artifacts). The artifacts in these simulations are approximately stationary and therefore ignore this tradeoff. 
eeg = artSim(eegDefaults);
eeg.duration         = 600;
eeg.lfpFrequency     = 23;
eeg.lfpAmplitude     = 100e-6;    % Oscillation peak amplitude
eeg.lfpPeakWidth     = 5;        % Oscillation bandwidth.
eeg.additive         = 100e-6;   % Background
eeg.zAmplitude       = 0.05;     % 5% heartbeat artifact
eeg.zFun             = @zHeartbeat;
eeg.reproducible    = false;    % Random draws each sim
tacsFrequency =10;
ar = arDefaults;

segmentDuration     =   [1 5 10 20 40];
nrBootstrap         =10;  % Takes a while to run...

nrSegmentDurations = numel(segmentDuration);
methods = ["FASTR","FBAR", "RBAR"];
nrMethods = numel(methods);
stims = ["AC" "DC"];
nrStims = numel(stims);
forbidden = nan(nrSegmentDurations,nrMethods,nrStims,nrBootstrap);
mre = nan(nrSegmentDurations,nrMethods,nrStims,nrBootstrap);

for bs = 1:nrBootstrap %[output:group:77b50c23]
    for stim = 1:nrStims
        if stims(stim)=="AC"
            eeg.tacsAmplitude  = 1e-3;
            eeg.tacsFrequency  =tacsFrequency;
            eeg.tdcsMean  = 0;
        elseif stims(stim)== "DC"
            eeg.tacsAmplitude  = 0;
            eeg.tacsFrequency  =0;
            eeg.tdcsMean  = 1e-3;
        end
        for m=1:nrMethods
            for  s = 1:nrSegmentDurations
                ar.segmentDuration= segmentDuration(s);
                if stims(stim)=="AC"                    
                    ar.tacsFrequency = tacsFrequency;
                elseif stims(stim) =="DC"                    
                    ar.tacsFrequency = 0;
                end
                results = simPlotEEG(eeg,ar,methods(m),freqRes =0.1,axs=[nan nan nan]); %[output:81d31a51] %[output:66666713] %[output:49aded03] %[output:5126534f] %[output:93c023f1] %[output:1449e92b] %[output:633b644b] %[output:9888522c] %[output:2c55930f] %[output:370c5b74] %[output:5c919d22] %[output:4ce2775e] %[output:2341f349] %[output:62410bfe] %[output:59caf527] %[output:7421a23c] %[output:117cd281] %[output:8d7b4d3d] %[output:9c1333e6] %[output:8310fc2b] %[output:17941ca9] %[output:11b7dfb4] %[output:79e726d9] %[output:4db9c8e0] %[output:0fbf709a] %[output:8b29be57] %[output:4633da1a] %[output:3eee673d] %[output:0b4ca738] %[output:8f4c2103] %[output:0faaaf71] %[output:22b74265] %[output:58ada2ce] %[output:028a47a5] %[output:067da3fd] %[output:1ec6f08c] %[output:30d759b0] %[output:4c2c7b2a] %[output:14073a83] %[output:17c9bb7b] %[output:6ae21864] %[output:936d5777] %[output:69409fb8] %[output:8772a2b3] %[output:39068050] %[output:9cb7fa45] %[output:9b216140] %[output:8875e69e] %[output:7df0324b] %[output:5b80719b] %[output:285a594b] %[output:26bbfbcd] %[output:9fe37c29] %[output:06fb5ed7] %[output:6ef382ac] %[output:28a7158f] %[output:050a15ac] %[output:58fb520a] %[output:096a005b] %[output:1f46bebc] %[output:860b2158] %[output:2fce9f67] %[output:7dda8149] %[output:6dc31164] %[output:4f78cf33] %[output:411683d5] %[output:3f7f1719] %[output:5e99bfb8] %[output:348d5bf8] %[output:645d5f21] %[output:39442f55] %[output:5b5e2f89] %[output:18e68f95] %[output:83564ef1] %[output:90072662] %[output:6dc11038] %[output:79b2ecbf] %[output:52f0725b] %[output:0b357484] %[output:919dcc2c] %[output:29cd0cfb] %[output:48650daa] %[output:043f3994] %[output:4fb9782d] %[output:760d5515] %[output:0d0ac9e4] %[output:2f8db9e1] %[output:3297d6ef] %[output:3a845e5c] %[output:3dc632e1] %[output:70ce5e85] %[output:34084a37] %[output:78476a5c] %[output:1a998123] %[output:9f262b22] %[output:435f80e8] %[output:1a6915ef] %[output:4aaeef53] %[output:95c0a335] %[output:09d944f3] %[output:62cf2edd] %[output:6e9d5926] %[output:0df71b85] %[output:10a4f0b2] %[output:18a0f7a0] %[output:3b3e6388] %[output:2dcf67b2] %[output:4475fd3c] %[output:63928a2b] %[output:8c999170] %[output:4c753a03] %[output:5c375ed3] %[output:9c9b5d4f] %[output:73613742] %[output:8ab509b5] %[output:324f56f2] %[output:4c8f6800] %[output:0d8412eb] %[output:0baef9fd] %[output:43e088fa] %[output:21a347ea] %[output:76e9c01a] %[output:424f8690] %[output:87ab9b2a] %[output:2436574d] %[output:446e8909] %[output:2bdceb25] %[output:7f6e1160] %[output:0fd062d6] %[output:3a370313] %[output:55f6fbb2] %[output:985c65f4] %[output:765bdb6a] %[output:134ffcd3] %[output:4ca826a1] %[output:57bdf057] %[output:5678b2ad] %[output:15d2cba3] %[output:5a47b612] %[output:2df2e2ec] %[output:1478158e] %[output:1652d2d0] %[output:0c4c10dc] %[output:9a5254fa] %[output:140be884] %[output:0ec0e9f4] %[output:40270b29] %[output:77ebba71] %[output:9438ddfe] %[output:38f81730] %[output:9e5a18d6] %[output:35404310] %[output:0f653d64] %[output:4b609dba] %[output:13f5a9c5] %[output:9cfe6125] %[output:8b75a482] %[output:923d7b8e] %[output:53d2aa00] %[output:5285a15e] %[output:1bcbe534] %[output:6849bad9] %[output:5ab3eb05] %[output:2d83c93e] %[output:65080dcb] %[output:41fd07d5] %[output:1fdbf10a] %[output:9af7094d] %[output:15165b7c] %[output:72651a67] %[output:7360c8eb] %[output:4f904319] %[output:3fbafe45] %[output:9e813562] %[output:94d34962] %[output:355fc017] %[output:30796dc7] %[output:02500bb8] %[output:9152d857] %[output:3862f869] %[output:091da503] %[output:56dde1ad] %[output:88270172] %[output:3dd67056] %[output:1455423b] %[output:15766db9] %[output:422c917c] %[output:132771d3] %[output:44464bf1] %[output:5c7801ed] %[output:4e1580c3] %[output:37b5184a] %[output:4d781eb3] %[output:8abdb0b1] %[output:538daf46] %[output:2db37613] %[output:4b622962] %[output:5925c155] %[output:3b590115] %[output:53d08feb] %[output:595d4a92] %[output:5040c1dd] %[output:55c9bd8c] %[output:89401e0b] %[output:608a8b63] %[output:97178091] %[output:15b18772] %[output:5271ba3d] %[output:253245bf] %[output:2396b75c] %[output:62289d9b] %[output:7bd28512] %[output:381a2171] %[output:93912da5] %[output:49bb7ebc] %[output:80594a35] %[output:970078b5] %[output:8d5df4cc] %[output:45187952] %[output:786b196b] %[output:5354bb89] %[output:5b436c79] %[output:0c72a226] %[output:8a3223b4] %[output:6591b8ef] %[output:8e06afb7] %[output:77a5ce55] %[output:57a6b548] %[output:243d05cd] %[output:0fabfea8] %[output:918bcdde] %[output:826ec091] %[output:2a937a2f] %[output:7d330241] %[output:12263340] %[output:03b363af] %[output:9fa4616b] %[output:1cbe91a4] %[output:0573c94f] %[output:93898757] %[output:76d0f55d]
                forbidden(s,m,stim,bs) = results.forbiddenBand;
                mre(s,m,stim,bs) = results.meanPctError;
            end
        end
    end
end %[output:group:77b50c23]
%%

mForbidden = mean(forbidden,4);
mMre  = mean(mre,4);
sdForbidden = std(forbidden,0,4);
sdMre = std(mre,0,4);

[f,axs] = fig('Name','SegmentDuration','paperCols',1,'height',5,'nrRows',1,'nrCols',1); %[output:2f359f33]
tiledlayout('flow') %[output:2f359f33]
for m=1:nrMethods %[output:group:387fbc9d]
    nexttile %[output:2f359f33]
    yyaxis left
    ploterr(segmentDuration',squeeze(mForbidden(:,m,:)),squeeze(sdForbidden(:,m,:)));
    xlabel 'Segment (s)'
    ylabel 'Forbidden (Hz)'
    yyaxis right
    ploterr(segmentDuration',squeeze(mMre(:,m,:)),squeeze(sdMre(:,m,:)))
    ylabel 'mre (%)'
    title (methods(m))    
end %[output:group:387fbc9d]



%[text] The figure confirms that the mre decrease rapidly with increasing segment duration in RBAR  and FBAR. 
%[text] FASTR has some oddities with longer segment durations, but that is probably due to the way the averaging is done across segments. 
